Properties.Octopus.Action.Script.ScriptBody:
$ErrorActionPreference = "Stop";

if ($PSEdition -eq "Core") {
    $PSStyle.OutputRendering = "PlainText"
}
$emailSubject = $OctopusParameters["SendEmail.Subject"]
$emailSmtpServer = $OctopusParameters["SendEmail.SmtpServer"]
$emailSmtpPort = $OctopusParameters["SendEmail.SmtpPort"]
$emailCredentialsUsername = $OctopusParameters["SendEmail.Credentials.Username"]
$emailCredentialsPassword = $OctopusParameters["SendEmail.Credentials.Password"]
$emailSecureSocketOption = $OctopusParameters["SendEmail.SecureSocketOption"]

$validSecureSocketOptions = @("None", "Auto", "SslOnConnect", "StartTls", "StartTlsWhenAvailable")
if(-not $validSecureSocketOptions.Contains($emailSecureSocketOption)) {
    Write-Error "Invalid SecureSocketOption: $emailSecureSocketOption. Must be one of: $($validSecureSocketOptions -join ", ")."
    return
}

$emailFromAddress = $OctopusParameters["SendEmail.FromAddress"]
$emailToAddresses = $OctopusParameters["SendEmail.TOAddresses"]
$emailCcAddresses = $OctopusParameters["SendEmail.CCAddresses"]
$emailReplyToAddress = $OctopusParameters["SendEmail.ReplyToAddress"]

$HtmlBody = $OctopusParameters["SendEmail.HtmlBody"]
$TextBody = $OctopusParameters["SendEmail.TextBody"]

# MimeKit 5 split into packages: "MimeKit" is now a meta-package with no DLLs.
# The core library is in MimeKit.Core. MimeKit.Core and MailKit are pinned to the
# same version so they always match. Override with SendEmail.MailKitVersion if set.
$mailKitVersion = $OctopusParameters["SendEmail.MailKitVersion"]
if ([string]::IsNullOrWhiteSpace($mailKitVersion)) {
    $mailKitVersion = "5.0.0"
}

# Load order matters: MimeKit.Core first, then MailKit.
$requiredPackages = @("MimeKit.Core", "MailKit")

function Get-BestLibDir {
    param($Package)

    if (-not $Package -or -not $Package.Source) {
        throw "Package object is null or has no Source. Did Install-Package/Get-Package succeed?"
    }

    $packageDir = Split-Path $Package.Source -Parent
    $root = Join-Path $packageDir "lib"
    if (-not (Test-Path $root)) {
        $contents = (Get-ChildItem -Path $packageDir).Name -join ", "
        throw "No lib folder for $($Package.Name) $($Package.Version). Package contains: $contents"
    }

    $runtimeMajor = [Environment]::Version.Major

    $best = Get-ChildItem -Path $root -Directory | ForEach-Object {
        $name = $_.Name
        $rank = if ($name -match '^net(\d+)\.\d+$' -and [int]$Matches[1] -le $runtimeMajor) { 1000 + [int]$Matches[1] }
                elseif ($name -eq "netstandard2.1") { 500 }
                elseif ($name -eq "netstandard2.0") { 400 }
                else { -1 }   # skips net462/net47/net48 and builds newer than the runtime
        [pscustomobject]@{ Dir = $_.FullName; Rank = $rank }
    } | Where-Object { $_.Rank -ge 0 -and (Get-ChildItem -Path $_.Dir -Filter *.dll) } |
        Sort-Object Rank -Descending | Select-Object -First 1

    if (-not $best) {
        $available = (Get-ChildItem -Path $root -Directory).Name -join ", "
        throw "No compatible build of $($Package.Name) under $root for .NET $runtimeMajor. Available: $available"
    }
    $best.Dir
}

Write-Verbose "Runtime: .NET $([Environment]::Version)"
Write-Verbose "Checking for MimeKit.Core and MailKit $mailKitVersion packages."

foreach ($packageName in $requiredPackages) {
    $package = Get-Package -Name $packageName -ProviderName NuGet -RequiredVersion $mailKitVersion -ErrorAction SilentlyContinue |
        Select-Object -First 1

    if ($null -eq $package) {
        Write-Output "Downloading $packageName $mailKitVersion from nuget.org."
        Install-Package -Name $packageName -RequiredVersion $mailKitVersion -Source "https://www.nuget.org/api/v2" -SkipDependencies -Force -Scope CurrentUser | Out-Null
        $package = Get-Package -Name $packageName -ProviderName NuGet -RequiredVersion $mailKitVersion | Select-Object -First 1
    }

    $libDir = Get-BestLibDir -Package $package

    foreach ($dll in Get-ChildItem -Path $libDir -Filter *.dll) {
        $asmName = [System.Reflection.AssemblyName]::GetAssemblyName($dll.FullName)
        $loaded = [AppDomain]::CurrentDomain.GetAssemblies() | Where-Object { $_.GetName().Name -eq $asmName.Name } | Select-Object -First 1

        if ($loaded) {
            if ($loaded.GetName().Version -ne $asmName.Version) {
                Write-Warning "$($asmName.Name) $($loaded.GetName().Version) is already loaded in this session; expected $($asmName.Version)."
            }
            continue
        }

        Write-Verbose "Loading $($asmName.Name) $($asmName.Version) from $($dll.FullName)"
        Add-Type -Path $dll.FullName
    }
}

# Validation/Setting of Secure Socket Options needed after libraries loaded
switch($emailSecureSocketOption) {
    "Auto" {
        $secureSocketOption = [MailKit.Security.SecureSocketOptions]::Auto
    }
    "None" {
        $secureSocketOption = [MailKit.Security.SecureSocketOptions]::None
    }
    "SslOnConnect" {
        $secureSocketOption = [MailKit.Security.SecureSocketOptions]::SslOnConnect
    }
    "StartTls" {
        $secureSocketOption = [MailKit.Security.SecureSocketOptions]::StartTls
    }
    "StartTlsWhenAvailable" {
        $secureSocketOption = [MailKit.Security.SecureSocketOptions]::StartTlsWhenAvailable
    }
    default {
        Write-Error "Invalid SecureSocketOption: $emailSecureSocketOption. Must be one of: $($validSecureSocketOptions -join ", ")."
        return
    }
}

$SMTP = New-Object MailKit.Net.Smtp.SmtpClient

try {
    $Message = New-Object MimeKit.MimeMessage
    $ContentBuilder = [MimeKit.BodyBuilder]::new()

    $ContentBuilder.HtmlBody = $HtmlBody
    $ContentBuilder.TextBody = $TextBody
    Write-Verbose "Setting From address: $emailFromAddress"
    $Message.From.Add($emailFromAddress)
    $toAddresses = $emailToAddresses -split ","
    Write-Verbose "Setting TO addresses: $emailToAddresses"
    foreach($toAddress in $toAddresses) {
        $Message.To.Add($toAddress.Trim())
    }

    if(-not [string]::IsNullOrWhitespace($emailCcAddresses)) {
        Write-Verbose "Setting CC addresses: $emailCcAddresses"
        $ccAddresses = $emailCcAddresses -split ","
        foreach($ccAddress in $ccAddresses) {
            $Message.Cc.Add($ccAddress.Trim())
        }
    }
    if(-not [string]::IsNullOrWhitespace($emailReplyToAddress)) {
        Write-Verbose "Setting ReplyTo address: $emailReplyToAddress"
        $Message.ReplyTo.Add($emailReplyToAddress)
    }

    Write-Verbose "Setting subject to: $emailSubject"
    $Message.Subject = $emailSubject
    Write-Verbose "Setting MimeMessage Body contents"
    $Message.Body = $ContentBuilder.ToMessageBody()
    Write-Verbose "Connecting to SMTP server: $emailSmtpServer on port: $emailSmtpPort (using SecureSocketOption=$emailSecureSocketOption)"
    $SMTP.Connect($emailSmtpServer, $emailSmtpPort, $secureSocketOption)
    Write-Verbose "Authenticating..."
    $SMTP.Authenticate($emailCredentialsUsername, $emailCredentialsPassword)
    Write-Output "Sending email..."
    # MailKit 5 replaced Send(MimeMessage) with Send(ISendRequest). Wrap the message in a
    # SendRequest and pass the CancellationToken explicitly so PowerShell resolves the overload.
    $sendRequest = [MailKit.SendRequest]::new($Message)
    $sendResult = $SMTP.Send($sendRequest, [System.Threading.CancellationToken]::None)
    Write-Verbose "Server response: $($sendResult.ResponseText)"
    if ($sendResult.RejectedRecipients.Count -gt 0) {
        Write-Warning "Rejected recipients: $($sendResult.RejectedRecipients -join ", ")"
    }
    Write-Output "Email sent."
    $SMTP.Disconnect($true)
}
finally {
    $SMTP.Dispose()
}
